#include "pch.h"
#include "SelectionMask.h"
namespace sct::core {
namespace {
void ValidateMask(const SelectionMask& mask){
    if(mask.width<1||mask.height<1||mask.width>32768||mask.height>32768||uint64_t(mask.width)*mask.height*4>512ULL*1024*1024||mask.spans.size()>524288)throw std::runtime_error("Invalid mask dimensions/complexity");
    int previousY=-1,previousRight=-1,left=mask.width,right=0;
    for(auto span:mask.spans){if(span.y<0||span.y>=mask.height||span.left<0||span.right>mask.width||span.left>=span.right||span.y<previousY||span.y==previousY&&span.left<=previousRight)throw std::runtime_error("Invalid mask spans");previousY=span.y;previousRight=span.right;left=std::min(left,span.left);right=std::max(right,span.right);}
    const CRect bounds=mask.spans.empty()?CRect{}:CRect(left,mask.spans.front().y,right,mask.spans.back().y+1);if(bounds!=mask.bounds)throw std::runtime_error("Invalid mask bounds");
}
}
void ValidateSelectionMask(const SelectionMask& mask){ValidateMask(mask);}
bool SelectionMask::Contains(POINT p)const{auto i=std::lower_bound(spans.begin(),spans.end(),p,[](const MaskSpan& a,POINT b){return a.y<b.y||(a.y==b.y&&a.right<=b.x);});return i!=spans.end()&&i->y==p.y&&p.x>=i->left&&p.x<i->right;}
std::shared_ptr<const SelectionMask> MakeSelectionMask(int width,int height,const SelectionMask* before,const Region& region,MaskCombine mode){
    if(width<1||height<1||width>32768||height>32768||uint64_t(width)*height*4>512ULL*1024*1024||region.points.size()>4096||before&&(before->width!=width||before->height!=height)||mode!=MaskCombine::Replace&&mode!=MaskCombine::Add&&mode!=MaskCombine::Subtract&&mode!=MaskCombine::Intersect)throw std::runtime_error("Invalid selection mask");
    if(region.shape!=RegionShape::Rectangle&&region.shape!=RegionShape::Ellipse&&region.shape!=RegionShape::Freehand)throw std::runtime_error("Invalid mask shape");for(auto p:region.points)if(p.x<0||p.y<0||p.x>width||p.y>height)throw std::runtime_error("Invalid mask point");
    if(before)ValidateMask(*before);
    CRect r=region.rect;r.NormalizeRect();r.IntersectRect(r,CRect(0,0,width,height));auto out=std::make_shared<SelectionMask>();out->width=width;out->height=height;size_t old=0;
    for(int y=0;y<height;++y){std::vector<std::pair<int,int>> a,b;while(before&&old<before->spans.size()&&before->spans[old].y<y)++old;while(before&&old<before->spans.size()&&before->spans[old].y==y){a.push_back({before->spans[old].left,before->spans[old].right});++old;}
        if(y>=r.top&&y<r.bottom&&!r.IsRectEmpty()){
            if(region.shape==RegionShape::Rectangle)b.push_back({r.left,r.right});
            else if(region.shape==RegionShape::Ellipse){const double rx=r.Width()/2.,ry=r.Height()/2.,cx=(r.left+r.right)/2.,cy=(r.top+r.bottom)/2.,dy=(y+.5-cy)/ry,dx=rx*std::sqrt(std::max(0.,1-dy*dy));int left=std::clamp<int>(static_cast<int>(std::ceil(cx-dx-.5)),r.left,r.right),right=std::clamp<int>(static_cast<int>(std::floor(cx+dx-.5))+1,r.left,r.right);if(right>left)b.push_back({left,right});}
            else if(region.shape==RegionShape::Freehand){std::vector<double> xs;const double row=y+.5;for(size_t i=0,j=region.points.empty()?0:region.points.size()-1;i<region.points.size();j=i++){const auto p=region.points[i],q=region.points[j];if((p.y>row)!=(q.y>row))xs.push_back(p.x+(row-p.y)*double(q.x-p.x)/(q.y-p.y));}std::sort(xs.begin(),xs.end());for(size_t i=0;i+1<xs.size();i+=2){int left=std::clamp(static_cast<int>(std::ceil(xs[i]-.5)),0,width),right=std::clamp(static_cast<int>(std::ceil(xs[i+1]-.5)),0,width);if(right>left)b.push_back({left,right});}}
            else throw std::runtime_error("Invalid selection shape");}
        std::vector<std::pair<int,int>> spans;if(mode==MaskCombine::Replace)spans=std::move(b);else if(mode==MaskCombine::Add){spans=std::move(a);spans.insert(spans.end(),b.begin(),b.end());std::sort(spans.begin(),spans.end());}else if(mode==MaskCombine::Intersect){size_t j=0;for(const auto x:a){while(j<b.size()&&b[j].second<=x.first)++j;for(size_t k=j;k<b.size()&&b[k].first<x.second;++k){const int left=std::max(x.first,b[k].first),right=std::min(x.second,b[k].second);if(left<right)spans.push_back({left,right});}}}else for(auto span:a){int start=span.first;for(auto cut:b){if(cut.second<=start||cut.first>=span.second)continue;if(cut.first>start)spans.push_back({start,std::min(cut.first,span.second)});start=std::max(start,cut.second);if(start>=span.second)break;}if(start<span.second)spans.push_back({start,span.second});}
        for(auto span:spans){if(!out->spans.empty()&&out->spans.back().y==y&&out->spans.back().right>=span.first)out->spans.back().right=std::max(out->spans.back().right,span.second);else out->spans.push_back({y,span.first,span.second});if(out->spans.size()>524288)throw std::runtime_error("Selection complexity limit");}}
    if(!out->spans.empty()){int left=width,right=0;for(auto span:out->spans){left=std::min(left,span.left);right=std::max(right,span.right);}out->bounds={left,out->spans.front().y,right,out->spans.back().y+1};}
    std::vector<std::pair<int,int>> previous;size_t offset=0;for(int y=out->bounds.top;y<=out->bounds.bottom&&!out->bounds.IsRectEmpty();++y){std::vector<std::pair<int,int>> row;while(offset<out->spans.size()&&out->spans[offset].y==y){const auto s=out->spans[offset++];row.push_back({s.left,s.right});out->outline.push_back({y,s.left,s.left,true});out->outline.push_back({y,s.right,s.right,true});}auto difference=[&](const auto& a,const auto& b){for(auto span:a){int start=span.first;for(auto cut:b){if(cut.second<=start||cut.first>=span.second)continue;if(cut.first>start)out->outline.push_back({y,start,std::min(cut.first,span.second),false});start=std::max(start,cut.second);if(start>=span.second)break;}if(start<span.second)out->outline.push_back({y,start,span.second,false});}};difference(row,previous);difference(previous,row);previous=std::move(row);if(out->outline.size()>1048576)throw std::runtime_error("Selection outline complexity limit");}return out;
}
namespace {void Check(const Image& image,const SelectionMask& mask){ValidateMask(mask);if(image.Empty()||image.width!=mask.width||image.height!=mask.height||uint64_t(image.width)*image.height*4!=image.pixels.size())throw std::runtime_error("Selection/image mismatch");}}
Image ExtractMasked(const Image& image,const SelectionMask& mask){Check(image,mask);if(mask.bounds.IsRectEmpty())throw std::runtime_error("Empty selected pixels");Image out;if(!out.Create(mask.bounds.Width(),mask.bounds.Height()))throw std::runtime_error("Selection allocation limit");std::fill(out.pixels.begin(),out.pixels.end(),BYTE{});for(auto span:mask.spans)memcpy(out.Row(span.y-mask.bounds.top)+(span.left-mask.bounds.left)*4,image.Row(span.y)+span.left*4,size_t(span.right-span.left)*4);return out;}
void ClearMasked(Image& image,const SelectionMask& mask){Check(image,mask);for(auto span:mask.spans)memset(image.Row(span.y)+span.left*4,0,size_t(span.right-span.left)*4);}
void RestoreOutsideMask(const Image& source,Image& output,const SelectionMask& mask){Check(source,mask);Check(output,mask);size_t index=0;for(int y=0;y<source.height;++y){int start=0;while(index<mask.spans.size()&&mask.spans[index].y==y){const auto span=mask.spans[index++];memcpy(output.Row(y)+start*4,source.Row(y)+start*4,size_t(span.left-start)*4);start=span.right;}memcpy(output.Row(y)+start*4,source.Row(y)+start*4,size_t(source.width-start)*4);}}
std::shared_ptr<const SelectionMask> ScaleMask(const SelectionMask& source,int width,int height){ValidateMask(source);if(width<1||height<1||width>900||height>700)throw std::runtime_error("Mask preview size limit");auto out=std::make_shared<SelectionMask>();out->width=width;out->height=height;int left=width,right=0;for(int y=0;y<height;++y){int start=-1;for(int x=0;x<=width;++x){const bool selected=x<width&&source.Contains({std::min(source.width-1,static_cast<int>((x+.5)*source.width/width)),std::min(source.height-1,static_cast<int>((y+.5)*source.height/height))});if(selected&&start<0)start=x;if(!selected&&start>=0){out->spans.push_back({y,start,x});left=std::min(left,start);right=std::max(right,x);start=-1;}}}if(!out->spans.empty())out->bounds={left,out->spans.front().y,right,out->spans.back().y+1};return out;}
}
